import { defineConfig } from 'vite';
import { resolve } from 'node:path';

/**
 * index.html is generated by scripts/prerender.mjs before Vite runs, and it
 * already carries the full stylesheet inline. Vite's only jobs here are to
 * bundle + hash the TypeScript and to emit the build into the Spring Boot
 * static directory so the backend serves one artefact.
 */
export default defineConfig({
  // Emit straight into the backend's classpath static folder.
  build: {
    outDir: resolve(__dirname, '../backend/src/main/resources/static'),
    emptyOutDir: true,
    target: 'es2022',
    cssMinify: 'esbuild',
    modulePreload: { polyfill: false },
    reportCompressedSize: true,
    assetsInlineLimit: 2048,
    rollupOptions: {
      output: {
        // Content-hashed so the backend can serve assets/* immutable for a year.
        entryFileNames: 'assets/[name].[hash].js',
        chunkFileNames: 'assets/[name].[hash].js',
        assetFileNames: 'assets/[name].[hash][extname]',
      },
    },
  },

  server: {
    port: 5173,
    // Talk to the Spring Boot app in dev so /api works without CORS.
    proxy: {
      '/api': { target: 'http://localhost:8080', changeOrigin: true },
    },
  },

  preview: { port: 4173 },
});
